import{_ as a,o as i,c as n,a4 as o}from"./chunks/framework.B6zrJok8.js";const m=JSON.parse('{"title":"Validation and Fixes","description":"","frontmatter":{"title":"Validation and Fixes"},"headers":[],"relativePath":"excel/validation-and-fixes.md","filePath":"excel/validation-and-fixes.md","lastUpdated":null}'),t={name:"excel/validation-and-fixes.md"};function r(s,e,l,d,h,c){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="validation-and-fixes" tabindex="-1">Validation and fixes <a class="header-anchor" href="#validation-and-fixes" aria-label="Permalink to &quot;Validation and fixes&quot;">​</a></h1><p>The CLI runs data quality checks before syncing to SFCC (e.g. when you run <code>make push</code> or <code>make validate</code>). This page explains common warnings and errors and how to fix them in the Excel wireframe.</p><h2 id="where-validation-runs" tabindex="-1">Where validation runs <a class="header-anchor" href="#where-validation-runs" aria-label="Permalink to &quot;Where validation runs&quot;">​</a></h2><ul><li><strong><code>make push</code></strong> — Runs checks before syncing; blocks on errors; prompts on warnings (unless <code>YES=1</code>).</li><li><strong><code>make validate DATE=YYYY-MM-DD</code></strong> — Runs the same checks without building or pushing. Use this to catch issues early.</li></ul><h2 id="common-errors-and-fixes" tabindex="-1">Common errors and fixes <a class="header-anchor" href="#common-errors-and-fixes" aria-label="Permalink to &quot;Common errors and fixes&quot;">​</a></h2><h3 id="missing-copy-launch" tabindex="-1">Missing copy (LAUNCH) <a class="header-anchor" href="#missing-copy-launch" aria-label="Permalink to &quot;Missing copy (LAUNCH)&quot;">​</a></h3><p><strong>Meaning:</strong> A row with ACTION=LAUNCH has no marketing copy (COPY / MESSAGE column empty).</p><p><strong>Fix in Excel:</strong> Fill in the COPY (or MESSAGE, COPY_MESSAGE, DISCLAIMER) column for that row. Every LAUNCH item should have copy for the template to render.</p><h3 id="missing-destination" tabindex="-1">Missing destination <a class="header-anchor" href="#missing-destination" aria-label="Permalink to &quot;Missing destination&quot;">​</a></h3><p><strong>Meaning:</strong> A link/destination is required but the DESTINATION ID (or link) column is empty for that row.</p><p><strong>Fix in Excel:</strong> Add the category ID, URL, or product ID in the destination column so the system can build the link.</p><h3 id="duplicate-ipid" tabindex="-1">Duplicate IPID <a class="header-anchor" href="#duplicate-ipid" aria-label="Permalink to &quot;Duplicate IPID&quot;">​</a></h3><p><strong>Meaning:</strong> Two or more items in the same refresh have the same IPID. Analytics and slot binding expect unique IPIDs per item.</p><p><strong>Fix in Excel:</strong> Change the IPID on one of the rows so each item is unique. Or adjust ZONE/position so the system generates different IPIDs.</p><h3 id="unknown-asset-type" tabindex="-1">Unknown asset type <a class="header-anchor" href="#unknown-asset-type" aria-label="Permalink to &quot;Unknown asset type&quot;">​</a></h3><p><strong>Meaning:</strong> The ASSET_TYPE (or SITE_LOCATION) value in the Excel row does not match any configured asset type.</p><p><strong>Fix in Excel:</strong> Use a recognized asset type (e.g. HOMEPAGE, PPH, POPUP, COUPONS, PLP_HEADER). Check <a href="./wireframe-format.html">Wireframe format</a> and config for the list. Fix typos or use the exact column values the system expects.</p><h3 id="missing-ipid" tabindex="-1">Missing IPID <a class="header-anchor" href="#missing-ipid" aria-label="Permalink to &quot;Missing IPID&quot;">​</a></h3><p><strong>Meaning:</strong> A LAUNCH item has no IPID and the system requires one.</p><p><strong>Fix in Excel:</strong> Add an IPID in the IPID column. See <a href="/guides/wireframe.html#ipid-format">Wireframe Guide</a> for the canonical structure.</p><h2 id="warnings-vs-errors" tabindex="-1">Warnings vs errors <a class="header-anchor" href="#warnings-vs-errors" aria-label="Permalink to &quot;Warnings vs errors&quot;">​</a></h2><ul><li><strong>Errors</strong> — Block push. You must fix the data and re-run pull/build/push.</li><li><strong>Warnings</strong> — The CLI will ask: cancel push or push anyway. Fix when possible.</li></ul><h2 id="after-fixing-excel" tabindex="-1">After fixing Excel <a class="header-anchor" href="#after-fixing-excel" aria-label="Permalink to &quot;After fixing Excel&quot;">​</a></h2><ol><li>Save the Excel file.</li><li>Run <code>make pull</code> to re-fetch and re-parse.</li><li>Run <code>make build</code> (or <code>make build FORCE=1</code> if you had already built).</li><li>Run <code>make push</code> again (or <code>make validate</code> to re-check without pushing).</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/troubleshooting/common-errors.html">Common Errors</a> — CLI-level error messages</li><li><a href="./wireframe-format.html">Wireframe format</a> — Required columns and values</li><li><a href="./how-changeouts-flow.html">How changeouts flow</a> — Command sequence</li></ul>',26)])])}const p=a(t,[["render",r]]);export{m as __pageData,p as default};
